using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServerExample;

/// <summary>
/// MCP tool class wrapping the Open-Meteo REST API.
///
/// DI rules:
///   - The SDK instantiates this class per tool invocation.
///   - Constructor parameters are resolved from the DI container.
///   - Each [McpServerTool] method can also accept special SDK-injected
///     parameters (CancellationToken, IMcpServer) alongside DI services.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // IHttpClientFactory is resolved from DI automatically.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool("get_weather")]
    [Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("weather");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var current = doc.RootElement.GetProperty("current");
        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool("get_forecast")]
    [Description("Get a 7-day daily temperature forecast for a location.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("weather");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&forecast_days=7";

        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var daily = doc.RootElement.GetProperty("daily");
        var dates = daily.GetProperty("time");
        var maxTemps = daily.GetProperty("temperature_2m_max");
        var minTemps = daily.GetProperty("temperature_2m_min");

        var lines = new List<string>();
        for (int i = 0; i < dates.GetArrayLength(); i++)
        {
            lines.Add($"{dates[i].GetString()}: "
                     + $"{minTemps[i].GetDouble()}°C – {maxTemps[i].GetDouble()}°C");
        }

        return string.Join("\n", lines);
    }
}

